def dehydrate_timedelta(value):
    """Dehydrator for `timedelta` values.

    Converts a :class:`datetime.timedelta` instance into a JSON‑serialisable
    representation (total seconds).  ``None`` is returned for a ``None`` input.
    A :class:`TypeError` is raised if the argument is not a ``timedelta``.

    :param value: a :class:`datetime.timedelta` instance
    :type value: datetime.timedelta
    :return: int or float representing the total number of seconds, or ``None``
    """
    if value is None:
        return None
    try:
        total = value.total_seconds()
    except AttributeError:
        raise TypeError("value must be a datetime.timedelta instance")
    # Return an int when there are no microseconds to keep the output compact
    if getattr(value, "microseconds", 0) == 0:
        return int(total)
    return total

