def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    # Basic validation: ensure value has required attributes
    if value is None:
        raise TypeError("Expected a Point instance, got None")
    required_attrs = ('lat', 'lon', 'time')
    for attr in required_attrs:
        if not hasattr(value, attr):
            raise TypeError(f"Expected a Point instance with attribute '{attr}'")
    try:
        lat = float(value.lat)
        lon = float(value.lon)
    except Exception as exc:
        raise TypeError("Point 'lat' and 'lon' must be convertible to float") from exc
    time = getattr(value, 'time')
    # Convert time to ISO format if possible
    if hasattr(time, 'isoformat') and callable(time.isoformat):
        try:
            time_str = time.isoformat()
        except Exception:
            time_str = str(time)
    else:
        time_str = str(time)
    return {'lat': lat, 'lon': lon, 'time': time_str}

