def keys(self):
    """Return the keys of the record.

    :return: list of key names
    """
    try:
        # Prefer a dedicated _keys attribute if present
        if hasattr(self, "_keys"):
            keys = self._keys
            # If it's a dictionary
            if isinstance(keys, dict):
                # If values are objects with a 'name' attribute, return those names
                if keys:
                    first_val = next(iter(keys.values()))
                    if hasattr(first_val, "name"):
                        return [getattr(v, "name", str(v)) for v in keys.values()]
                # Otherwise return the dictionary keys
                return [str(k) for k in keys.keys()]
            # If it's a list or tuple of key objects
            if isinstance(keys, (list, tuple)):
                if keys and hasattr(keys[0], "name"):
                    return [getattr(k, "name", str(k)) for k in keys]
                return [str(k) for k in keys]

        # Fallback to a 'record' attribute if it exists
        if hasattr(self, "record"):
            rec = self.record
            if isinstance(rec, dict):
                return [str(k) for k in rec.keys()]
            if hasattr(rec, "__dict__"):
                return [str(k) for k in rec.__dict__.keys()]

        # As a last resort, return public attributes of the instance
        return [attr for attr in dir(self) if not attr.startswith("_")]

    except Exception:
        # In case of any unexpected error, return an empty list
        return []

