def index(self, key):
    """Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    # Try to use a dedicated index list if available
    try:
        return self._index.index(key)
    except AttributeError:
        # Fallback to data list
        try:
            return self._data.index(key)
        except AttributeError:
            # If data is a mapping, search its keys
            try:
                return list(self._data.keys()).index(key)
            except Exception:
                raise KeyError(f"Key {key!r} not found")
        except ValueError:
            raise KeyError(f"Key {key!r} not found")
    except ValueError:
        raise KeyError(f"Key {key!r} not found")

