def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to retrieve items as a list of (key, value) tuples
    try:
        items = list(self.iteritems())
    except AttributeError:
        try:
            items = list(self.items())
        except AttributeError:
            raise TypeError("Object does not support iteration over items")

    # If no keys specified, return all values
    if not keys:
        return [value for _, value in items]

    # Build the result list based on provided keys
    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as positional index
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of range")
            result.append(items[key][1])
        elif isinstance(key, str):
            # Treat as dictionary key
            found = False
            for k, v in items:
                if k == key:
                    result.append(v)
                    found = True
                    break
            if not found:
                raise KeyError(f"Key '{key}' not found")
        else:
            raise TypeError(f"Unsupported key type: {type(key).__name__}")
    return result

