def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Assume the record stores field names in self._keys and values in self._values
    keys_list = getattr(self, "_keys", None)
    values_list = getattr(self, "_values", None)

    if keys_list is None or values_list is None:
        raise AttributeError("Record object must have '_keys' and '_values' attributes")

    if not keys:
        # Return all key/value pairs
        return dict(zip(keys_list, values_list))

    result = {}
    for k in keys:
        if isinstance(k, int):
            idx = k
            if idx < 0 or idx >= len(keys_list):
                raise IndexError(f"Index {idx} out of bounds")
            key_name = keys_list[idx]
            result[key_name] = values_list[idx]
        elif isinstance(k, str):
            if k in keys_list:
                idx = keys_list.index(k)
                result[k] = values_list[idx]
            else:
                result[k] = None
        else:
            raise TypeError(f"Key {k!r} must be an int or str")
    return result

