def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate class name
    if not isinstance(name, str) or not name.isidentifier():
        raise TypeError(f"Invalid class name: {name!r}")

    # Validate srid_map
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dict")

    # Prepare namespace and annotations
    namespace = {}
    annotations = {}

    for item in fields:
        if isinstance(item, str):
            field_name = item
            field_type = 'typing.Any'
        elif isinstance(item, tuple):
            if len(item) == 2:
                field_name, field_type = item
            elif len(item) == 3:
                field_name, field_type, spec = item
                namespace[field_name] = spec
            else:
                raise TypeError(f"Invalid field specification: {item!r}")
        else:
            raise TypeError(f"Invalid field specification: {item!r}")

        if not isinstance(field_name, str) or not field_name.isidentifier():
            raise TypeError(f"Field name must be a valid identifier: {field_name!r}")

        annotations[field_name] = field_type

    namespace['__annotations__'] = annotations
    namespace['srid_map'] = srid_map

    # Base class for the new Point subclass
    Base = globals().get('Point', object)

    # Create the new class
    cls = type(name, (Base,), namespace)
    return cls

