def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _legacy_mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """
    # Collect all unique elements in order of first appearance
    appearance = {}
    for ordering in orderings:
        for elem in ordering:
            if elem not in appearance:
                appearance[elem] = len(appearance)

    # Build adjacency list and indegree counts
    adj = {elem: set() for elem in appearance}
    indegree = {elem: 0 for elem in appearance}
    for ordering in orderings:
        for i in range(len(ordering) - 1):
            a, b = ordering[i], ordering[i + 1]
            if b not in adj[a]:
                adj[a].add(b)
                indegree[b] += 1

    # Kahn's algorithm with appearance-based tie-breaking
    result = []
    zero_queue = [elem for elem, deg in indegree.items() if deg == 0]
    while zero_queue:
        # Sort by appearance index to get deterministic order
        zero_queue.sort(key=lambda x: appearance[x])
        node = zero_queue.pop(0)
        result.append(node)
        for neigh in adj[node]:
            indegree[neigh] -= 1
            if indegree[neigh] == 0:
                zero_queue.append(neigh)

    if len(result) != len(appearance):
        raise ValueError("Cycle detected in orderings; cannot merge.")
    return result

