def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")
    result = []
    seen = set()
    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"Element {cls!r} is not a class")
        if cls in seen:
            continue
        # Determine if cls is a superclass of any other class in the list
        redundant = False
        for other in classes:
            if other is cls:
                continue
            if issubclass(other, cls):
                redundant = True
                break
        if not redundant:
            result.append(cls)
            seen.add(cls)
    return result

