    """Return attribute names and descriptions defined by interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean value")

    results = []

    # Collect attributes defined directly on the class (excluding private ones)
    for name, value in self.__class__.__dict__.items():
        if name.startswith("_"):
            continue
        try:
            description = getattr(value, "__doc__", "")
            if description is None:
                description = ""
        except Exception:
            description = ""
        results.append((name, description))

    if all:
        # Include inherited attributes that were not already added
        for name in dir(self):
            if name.startswith("_"):
                continue
            if any(name == existing_name for existing_name, _ in results):
                continue
            try:
                attr = getattr(self, name)
                description = getattr(attr, "__doc__", "")
                if description is None:
                    description = ""
            except Exception:
                description = ""
            results.append((name, description))

    return results

