def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("Parameter 'all' must be a boolean.")
    try:
        cls = self.__class__
        # Start with annotations (type hints) if present
        names = list(getattr(cls, "__annotations__", {}))
        # Add class-level attributes that are not private and not callable
        for name, value in cls.__dict__.items():
            if name.startswith("_") or callable(value):
                continue
            if name not in names:
                names.append(name)
        # Include __slots__ if defined
        if hasattr(cls, "__slots__"):
            slots = cls.__slots__
            if isinstance(slots, str):
                slots = [slots]
            for slot in slots:
                if slot not in names:
                    names.append(slot)
        # If requested, include attributes from base classes
        if all:
            for base in cls.__mro__[1:]:
                for name in getattr(base, "__annotations__", {}):
                    if name not in names:
                        names.append(name)
                for name, value in base.__dict__.items():
                    if name.startswith("_") or callable(value):
                        continue
                    if name not in names:
                        names.append(name)
                if hasattr(base, "__slots__"):
                    slots = base.__slots__
                    if isinstance(slots, str):
                        slots = [slots]
                    for slot in slots:
                        if slot not in names:
                            names.append(slot)
        return names
    except Exception as exc:
        raise RuntimeError(f"Error retrieving interface names: {exc}") from exc

