def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dictionary
    try:
        self.context = {}
    except AttributeError:
        # If the attribute does not exist, create it
        self.context = {}

    # Reinitialize bins
    try:
        # If an initial value is provided, use it
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # If the initial value is a scalar, replicate it across existing bins
            if isinstance(self.initial_value, (int, float)):
                if hasattr(self, "bins") and self.bins is not None:
                    self.bins = [self.initial_value] * len(self.bins)
                else:
                    # No existing bins; create a single bin
                    self.bins = [self.initial_value]
            else:
                # Assume the initial value is an iterable matching the desired bin shape
                self.bins = list(self.initial_value)
        else:
            # No explicit initial value; fall back to make_bins if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If make_bins is not defined, default to an empty list of bins
                self.bins = []
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

