def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Exclude Source sequences outright
    if isinstance(seq, Source):
        return False
    # A single FillRequest is acceptable
    if isinstance(seq, FillRequest):
        return True
    # Strings and bytes should not be treated as sequences of items
    if isinstance(seq, (str, bytes)):
        return False
    # Try to iterate over seq; if not iterable, return False
    try:
        iterator = iter(seq)
    except TypeError:
        return False
    # Check if any element is a FillRequest
    return any(isinstance(item, FillRequest) for item in iterator)

