def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is an InventoryValidator instance
    if not isinstance(prior, InventoryValidator):
        raise TypeError(
            f"prior must be an InventoryValidator instance, got {type(prior).__name__}"
        )

    # Retrieve and validate version attributes
    try:
        self_version = self.version
    except AttributeError:
        raise AttributeError("self object does not have a 'version' attribute")
    try:
        prior_version = prior.version
    except AttributeError:
        raise AttributeError("prior object does not have a 'version' attribute")

    # Prior version must be older than current version
    if prior_version >= self_version:
        raise ValueError(
            f"prior version ({prior_version}) must be older than current version ({self_version})"
        )

    # Retrieve inventory attributes
    try:
        self_inventory = self.inventory
    except AttributeError:
        raise AttributeError("self object does not have an 'inventory' attribute")
    try:
        prior_inventory = prior.inventory
    except AttributeError:
        raise AttributeError("prior object does not have an 'inventory' attribute")

    # Inventory should be a mapping type (e.g., dict)
    if not isinstance(self_inventory, dict) or not isinstance(prior_inventory, dict):
        raise TypeError("inventory attributes must be dictionaries")

    # Prior inventory keys must be a subset of current inventory keys
    prior_keys = set(prior_inventory.keys())
    current_keys = set(self_inventory.keys())
    if not prior_keys.issubset(current_keys):
        missing = prior_keys - current_keys
        raise ValueError(
            f"prior inventory contains keys not present in current inventory: {missing}"
        )

    # Optional: ensure that overlapping entries match
    for key in prior_keys:
        if self_inventory[key] != prior_inventory[key]:
            raise ValueError(
                f"inventory entry for key '{key}' differs between current and prior versions"
            )

    # All checks passed
    return True

