def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(inventory, (dict, list)):
        raise TypeError("inventory must be a dict or a list")
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    # Resolve 'latest' to the maximum version string present in the inventory
    if version == "latest":
        all_versions = set()
        if isinstance(inventory, dict):
            for ver_map in inventory.values():
                if isinstance(ver_map, dict):
                    all_versions.update(ver_map.keys())
        else:  # list
            for entry in inventory:
                if isinstance(entry, (list, tuple)) and len(entry) == 3:
                    all_versions.add(entry[1])
        if not all_versions:
            raise ValueError("No versions found in inventory to resolve 'latest'")
        version = max(all_versions)

    result = {}

    if isinstance(inventory, dict):
        # Expected format: {logical_path: {version: iterable_of_files}}
        for logical_path, ver_map in inventory.items():
            if not isinstance(ver_map, dict):
                continue
            files = set()
            for ver, content in ver_map.items():
                try:
                    if ver == version or ver > version:
                        if isinstance(content, (list, set, tuple)):
                            files.update(content)
                        else:
                            files.add(content)
                except Exception:
                    # Skip entries that cause comparison errors
                    continue
            if files:
                result[logical_path] = files
    else:  # list
        # Expected format: [(logical_path, version, content_file), ...]
        for entry in inventory:
            if not isinstance(entry, (list, tuple)) or len(entry) != 3:
                continue
            logical_path, ver, content_file = entry
            if not isinstance(logical_path, str) or not isinstance(ver, str):
                continue
            try:
                if ver == version or ver > version:
                    result.setdefault(logical_path, set()).add(content_file)
            except Exception:
                continue

    return result

