def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is iterable and convert to a set for fast lookup
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise ValueError("manifest_files must be an iterable of file names")

    # Basic type check for the fixity block
    if not isinstance(fixity, dict):
        raise ValueError("fixity must be a dictionary")

    # Required keys in the fixity block
    required_keys = {"file", "checksum", "algorithm"}
    missing_keys = required_keys - fixity.keys()
    if missing_keys:
        raise ValueError(f"fixity missing required keys: {', '.join(sorted(missing_keys))}")

    # Validate the 'file' entry
    file_name = fixity["file"]
    if not isinstance(file_name, str):
        raise ValueError("fixity 'file' must be a string")
    if file_name not in manifest_set:
        raise ValueError(f"fixity references unknown file '{file_name}' not in manifest")

    # Validate the 'checksum' entry
    checksum = fixity["checksum"]
    if not isinstance(checksum, str):
        raise ValueError("fixity 'checksum' must be a string")
    # Simple hex validation
    if not all(c in "0123456789abcdefABCDEF" for c in checksum):
        raise ValueError("fixity 'checksum' must be a hex string")

    # Validate the 'algorithm' entry
    algorithm = fixity["algorithm"]
    if not isinstance(algorithm, str):
        raise ValueError("fixity 'algorithm' must be a string")
    known_algorithms = {"md5", "sha1", "sha256", "sha512"}
    if algorithm.lower() not in known_algorithms:
        raise ValueError(
            f"Unknown checksum algorithm '{algorithm}'. "
            f"Known algorithms: {', '.join(sorted(known_algorithms))}"
        )

    return True

