def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First collect basenames of all XML files
            xml_basenames = set()
            for info in zf.infolist():
                if info.is_dir():
                    continue
                if info.filename.lower().endswith('.xml'):
                    basename = os.path.splitext(os.path.basename(info.filename))[0]
                    xml_basenames.add(basename)

            # Now group all files that share those basenames
            for info in zf.infolist():
                if info.is_dir():
                    continue
                name = info.filename
                basename = os.path.splitext(os.path.basename(name))[0]
                if basename in xml_basenames:
                    result.setdefault(basename, {})[name] = zf.read(name)
    except FileNotFoundError:
        # If the zip file does not exist, return empty dict
        return {}
    except zipfile.BadZipFile:
        # If the file is not a zip, return empty dict
        return {}
    except Exception:
        # For any other exception, re-raise to avoid silent failures
        raise
    return result

