def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    try:
        # Ensure indent is a non-negative integer
        try:
            indent_val = int(indent)
            if indent_val < 0:
                indent_val = 0
        except Exception:
            indent_val = 0

        import pprint
        formatted = pprint.pformat(self, indent=indent_val)
        if debug:
            header = f"{self.__class__.__name__} (id={id(self)})"
            return f"{header}\n{formatted}"
        return formatted
    except Exception as e:
        # Fallback to repr with error message
        return f"<Error pretty printing {self.__class__.__name__}: {e}>"

