def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Default style
    if style is None:
        style = 'full'
    # Ensure pieces is iterable
    if pieces is None:
        return ''
    try:
        iter(pieces)
    except TypeError:
        raise TypeError('pieces must be an iterable of version components')
    # Convert each component to string
    parts = [str(p) for p in pieces]
    # Normalise style
    if isinstance(style, str):
        style = style.lower()
    else:
        raise TypeError('style must be a string')
    # Render according to style
    if style == 'semver':
        # Join first three components (major.minor.patch)
        return '.'.join(parts[:3])
    elif style == 'short':
        # Join first two components
        return '.'.join(parts[:2])
    elif style == 'full':
        return '.'.join(parts)
    elif style == 'tuple':
        return str(tuple(parts))
    elif style == 'list':
        return str(parts)
    elif style == 'json':
        import json
        return json.dumps(parts)
    else:
        raise ValueError(f'Unknown style: {style}')

