def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os
    import shlex

    # Build the command list
    if isinstance(commands, str):
        cmd_list = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        cmd_list = list(commands)
    else:
        raise TypeError("commands must be a string or a list/tuple of strings")

    if isinstance(args, str):
        args_list = shlex.split(args)
    elif isinstance(args, (list, tuple)):
        args_list = list(args)
    elif args is None:
        args_list = []
    else:
        raise TypeError("args must be a string, a list/tuple of strings, or None")

    full_cmd = cmd_list + args_list

    if verbose:
        print("Running command:", " ".join(full_cmd))

    # Prepare environment
    env_dict = os.environ.copy()
    if env is not None:
        if not isinstance(env, dict):
            raise TypeError("env must be a dictionary")
        env_dict.update(env)

    # Handle stderr visibility
    stderr = subprocess.DEVNULL if hide_stderr else None

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env_dict,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=True,
        )
        return result.stdout
    except subprocess.CalledProcessError as e:
        # Re-raise with the same information
        raise subprocess.CalledProcessError(
            e.returncode, e.cmd, output=e.output, stderr=e.stderr
        )
    except OSError as e:
        raise RuntimeError(f"Failed to execute command {full_cmd!r}: {e}") from e

