def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool')

    # Ensure a storage root is available
    if not hasattr(self, '_storage_root'):
        raise RuntimeError('Storage root not initialized')

    # Helper to iterate over all objects in the hierarchy
    def _iter_objects(obj):
        yield obj
        for child in getattr(obj, 'children', []):
            yield from _iter_objects(child)

    num_objects = 0
    good_objects = 0

    for obj in _iter_objects(self._storage_root):
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                validate_method = getattr(obj, 'validate', None)
                if callable(validate_method):
                    validate_method()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Validation error for object {obj!r}: {exc}')

        # Check digests if requested and object still considered valid
        if check_digests and is_valid:
            try:
                expected = getattr(obj, 'digest', None)
                compute = getattr(obj, 'compute_digest', None)
                if expected is not None and callable(compute):
                    actual = compute()
                    if expected != actual:
                        is_valid = False
                        if show_warnings:
                            print(f'Digest mismatch for object {obj!r}: expected {expected}, got {actual}')
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f'Digest check error for object {obj!r}: {exc}')

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

