def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("self.root_inventory must be a dict containing the root inventory")
    # Ensure we have a place to record differences
    if not hasattr(self, "different_digests"):
        self.different_digests = {}
    cumulative = {}
    for idx, vdir in enumerate(version_dirs, start=1):
        # Build path to inventory file; assume JSON format
        inv_path = os.path.join(self.base_dir, vdir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found for version '{vdir}': {inv_path}")
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inv = json.load(fh)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid JSON in inventory for version '{vdir}': {exc}") from exc
        if not isinstance(inv, dict):
            raise ValueError(f"Inventory for version '{vdir}' must be a mapping, got {type(inv).__name__}")
        # Compare each entry to root inventory
        for key, digest in inv.items():
            root_digest = self.root_inventory.get(key)
            if root_digest is not None and digest != root_digest:
                self.different_digests.setdefault(key, []).append(
                    (vdir, root_digest, digest)
                )
        # Validate that all previous entries are present
        if idx > 1:
            missing = set(cumulative) - set(inv)
            if missing:
                raise ValueError(
                    f"Version '{vdir}' inventory is missing entries from previous versions: {sorted(missing)}"
                )
        # Record any digest changes relative to cumulative
        for key, digest in inv.items():
            prev_digest = cumulative.get(key)
            if prev_digest is not None and digest != prev_digest:
                self.different_digests.setdefault(key, []).append(
                    (vdir, prev_digest, digest)
                )
        cumulative = inv
    return self

