def int_to_string(number: int, alphabet: list, padding: int = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non‑negative")
    if not isinstance(alphabet, (list, tuple)):
        raise TypeError(f"alphabet must be a list or tuple, got {type(alphabet).__name__}")
    if len(alphabet) == 0:
        raise ValueError("alphabet must contain at least one character")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet must contain unique characters")
    if padding is not None and not isinstance(padding, int):
        raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non‑negative")

    base = len(alphabet)

    # Special case for zero
    if number == 0:
        result = alphabet[0]
        if padding is not None:
            # Ensure at least one digit is produced
            result = alphabet[0] * max(padding, 1)
        return result

    digits = []
    n = number
    while n > 0:
        n, rem = divmod(n, base)
        digits.append(alphabet[rem])

    # Most significant digit first
    digits.reverse()
    result = "".join(digits)

    # Apply padding if requested
    if padding is not None:
        if len(result) < padding:
            result = alphabet[0] * (padding - len(result)) + result

    return result

