def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError("subclasses() expects a class type")
    seen = set()
    queue = [cls]
    while queue:
        current = queue.pop()
        try:
            subs = current.__subclasses__()
        except Exception:
            continue
        for sub in subs:
            if sub not in seen:
                seen.add(sub)
                queue.append(sub)
    return seen

