def _resolve_string(matcher):
    """
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Extract the variable name. Prefer a named group 'name', otherwise use the first positional group.
    if hasattr(matcher, "groupdict") and "name" in matcher.groupdict():
        name = matcher.group("name")
    else:
        try:
            name = matcher.group(1)
        except IndexError:
            raise ValueError("Matcher does not contain a variable name")

    # Extract the default value if present. Prefer a named group 'default', otherwise use the second positional group.
    default = None
    if hasattr(matcher, "groupdict") and "default" in matcher.groupdict():
        default = matcher.group("default")
    else:
        try:
            default = matcher.group(2)
        except IndexError:
            default = None

    # Retrieve the environment variable or use the default if available.
    if name in os.environ:
        return os.environ[name]
    if default is not None:
        return default

    # No value found and no default provided – raise an informative error.
    raise KeyError(f"Environment variable '{name}' not found and no default provided")

