def build_app_logger(name='app', logfile='app.log', debug=True):
    """
    General purpose application logger. Useful mainly for debugging.
    """
    # Validate arguments
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    if not isinstance(logfile, str):
        raise TypeError(f"logfile must be a string, got {type(logfile).__name__}")
    if not isinstance(debug, bool):
        raise TypeError(f"debug must be a bool, got {type(debug).__name__}")

    logger = logging.getLogger(name)
    level = logging.DEBUG if debug else logging.INFO
    logger.setLevel(level)

    # Formatter for all handlers
    formatter = logging.Formatter(
        fmt='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
        datefmt='%Y-%m-%d %H:%M:%S'
    )

    # Helper to check if a handler already exists
    def handler_exists(handler_type, **kwargs):
        for h in logger.handlers:
            if isinstance(h, handler_type):
                if handler_type is logging.FileHandler:
                    if os.path.abspath(h.baseFilename) == os.path.abspath(kwargs.get('filename', '')):
                        return True
                elif handler_type is logging.StreamHandler:
                    if h.stream == kwargs.get('stream'):
                        return True
        return False

    # Add file handler if not already present
    if not handler_exists(logging.FileHandler, filename=logfile):
        try:
            # Ensure directory exists
            log_dir = os.path.dirname(os.path.abspath(logfile))
            if log_dir and not os.path.exists(log_dir):
                os.makedirs(log_dir, exist_ok=True)
            file_handler = logging.FileHandler(logfile, encoding='utf-8')
            file_handler.setLevel(level)
            file_handler.setFormatter(formatter)
            logger.addHandler(file_handler)
        except Exception as e:
            # If file handler cannot be created, fall back to console
            print(f"Failed to create file handler for '{logfile}': {e}", file=sys.stderr)

    # Add stream handler to stdout if not already present
    if not handler_exists(logging.StreamHandler, stream=sys.stdout):
        stream_handler = logging.StreamHandler(sys.stdout)
        stream_handler.setLevel(level)
        stream_handler.setFormatter(formatter)
        logger.addHandler(stream_handler)

    return logger

