def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import json
    import logging
    try:
        import yaml
    except ImportError:
        yaml = None
    try:
        import toml
    except ImportError:
        toml = None

    logger = logging.getLogger('config_loader')
    configs = {}
    error_records = []

    def _create_error_record(msg, exc=None):
        record = logging.LogRecord(
            name='config_loader',
            level=logging.ERROR,
            pathname='',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc
        )
        return record

    def _resolve_env_in_value(value):
        if isinstance(value, str):
            # simple ${VAR} replacement
            import re
            pattern = re.compile(r'\$\{([^}]+)\}')
            def repl(match):
                var = match.group(1)
                return os.getenv(var, '')
            return pattern.sub(repl, value)
        return value

    def _resolve_env_in_dict(d):
        if isinstance(d, dict):
            return {k: _resolve_env_in_dict(_resolve_env_in_value(v)) for k, v in d.items()}
        elif isinstance(d, list):
            return [_resolve_env_in_dict(_resolve_env_in_value(v)) for v in d]
        else:
            return _resolve_env_in_value(d)

    for fname in config_filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"Configuration file not found: {fname}")
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            # Determine format by extension
            ext = os.path.splitext(fname)[1].lower()
            if ext in ('.yaml', '.yml'):
                if yaml is None:
                    raise ImportError("PyYAML is required for YAML files")
                parsed = yaml.safe_load(raw)
            elif ext == '.toml':
                if toml is None:
                    raise ImportError("toml is required for TOML files")
                parsed = toml.loads(raw)
            elif ext == '.json':
                parsed = json.loads(raw)
            else:
                # Try JSON first, then YAML, then TOML
                try:
                    parsed = json.loads(raw)
                except Exception:
                    try:
                        if yaml is None:
                            raise ImportError("PyYAML is required for YAML files")
                        parsed = yaml.safe_load(raw)
                    except Exception:
                        if toml is None:
                            raise ImportError("toml is required for TOML files")
                        parsed = toml.loads(raw)
            if not isinstance(parsed, dict):
                raise ValueError("Parsed configuration is not a dictionary")
            if resolve_env:
                parsed = _resolve_env_in_dict(parsed)
            if overrides:
                # shallow merge: overrides overwrite parsed
                parsed.update(overrides)
            configs[fname] = parsed
        except Exception as exc:
            msg = f"Error loading configuration '{fname}': {exc}"
            error_records.append(_create_error_record(msg, exc_info=exc))
    return configs, error_records

