def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a string or bytes, treat as a string
    if isinstance(seq, (str, bytes)):
        return (seq, 'string')
    # If seq is a file-like object, read its contents
    if hasattr(seq, 'read'):
        try:
            data = seq.read(bufsize) if bufsize is not None else seq.read()
        except Exception as e:
            raise IOError("Error reading from file-like object: %s" % e)
        return (data, 'file')
    # If seq is a sequence type (list or tuple), return it directly
    if isinstance(seq, (list, tuple)):
        return (seq, 'sequence')
    # If seq is an iterator or generator, return it as a generator
    if hasattr(seq, '__iter__'):
        return (seq, 'generator')
    # Unsupported type
    raise TypeError("Unsupported sequence type: %r" % type(seq))

