def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Validate the interface argument
    if not isinstance(iface, type):
        raise TypeError(f"iface must be a type or class, got {type(iface).__name__}")

    # Helper to raise or return based on tentative flag
    def _handle_failure(message):
        if tentative:
            return False
        raise TypeError(message)

    # If candidate is a class, use issubclass
    if isinstance(candidate, type):
        if issubclass(candidate, iface):
            return True
        return _handle_failure(f"{candidate.__name__} does not implement interface {iface.__name__}")

    # If candidate is an instance, use isinstance
    if isinstance(candidate, iface):
        return True

    # Fallback: check that candidate has all non-special attributes of iface
    missing_attrs = []
    for attr in dir(iface):
        if attr.startswith("__"):
            continue
        if not hasattr(candidate, attr):
            missing_attrs.append(attr)

    if missing_attrs:
        return _handle_failure(
            f"{candidate!r} does not implement interface {iface.__name__}: missing attributes {missing_attrs}"
        )

    # If all checks pass, candidate is considered valid
    return True

