def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # If an explicit metaclass is supplied, use it
    if explicit_mc is not None:
        # Resolve string names to actual objects if possible
        if isinstance(explicit_mc, str):
            try:
                explicit_mc = globals()[explicit_mc]
            except KeyError:
                raise TypeError(f"Explicit metaclass name '{explicit_mc}' not found")
        if not isinstance(explicit_mc, type):
            raise TypeError(f"Explicit metaclass must be a type, got {type(explicit_mc).__name__}")
        return explicit_mc

    # No explicit metaclass: determine from bases
    if not bases:
        return type

    # Gather the metaclasses of each base
    metaclasses = [type(b) for b in bases]

    # If all metaclasses are identical, return that one
    first = metaclasses[0]
    if all(mc is first for mc in metaclasses):
        return first

    # Find the most derived metaclass (subclass of all others)
    for mc in metaclasses:
        if all(issubclass(mc, other) for other in metaclasses):
            return mc

    # If no single metaclass can satisfy all bases, raise an error
    names = ", ".join(mc.__name__ for mc in metaclasses)
    raise TypeError(f"metaclass conflict: {names}")

