def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not hasattr(self, "_cache") or not self._cache:
        raise KeyError("cache is empty")
    # If the underlying storage is an OrderedDict, popitem(last=False) removes the LRU entry.
    try:
        return self._cache.popitem(last=False)
    except TypeError:
        # Fallback for plain dict: assume an auxiliary order list exists.
        if hasattr(self, "_order") and self._order:
            key = self._order.pop(0)
            return key, self._cache.pop(key)
        raise KeyError("cache is empty") from None

