        rest = rest[:tz_match.start()]
    else:
        tz_str = None
    # Parse date
    # ISO week date
    m = re.match(r'(?P<year>\d{4})-?W(?P<week>\d{2})(?:-?(?P<weekday>\d))?$', date_part)
    if m:
        year = int(m.group('year'))
        week = int(m.group('week'))
        weekday = int(m.group('weekday') or 1)
        date = datetime.date.fromisocalendar(year, week, weekday)
    else:
        # Regular date
        m = re.match(r'(?P<year>\d{4})(?:-?(?P<month>\d{2})(?:-?(?P<day>\d{2}))?)?$', date_part)
        if not m:
            raise ValueError(f"Invalid date part: {date_part}")
        year = int(m.group('year'))
        month = int(m.group('month') or 1)
        day = int(m.group('day') or 1)
