        if isinstance(path, str) and path.startswith('/_matrix'):
            return True
        # Check headers for Matrix‑specific markers
        headers = getattr(request, 'headers', None)
        if headers:
            get_header = getattr(headers, 'get', None)
            if get_header:
                if get_header('X-Matrix-Request') or get_header('X-Matrix-Client'):
                    return True
                if get_header('Content-Type', '').startswith('application/json'):
                    return True
        # Check META (Django style) for Matrix‑specific markers
        meta = getattr(request, 'META', None)
        if meta and isinstance(meta, dict):
            if meta.get('HTTP_X_MATRIX_REQUEST') or meta.get('HTTP_X_MATRIX_CLIENT'):
                return True
            if meta.get('CONTENT_TYPE', '').startswith('application/json'):
                return True
        return False
    except Exception:
        return False

