def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            # Ensure 'links' key exists
            links = data.get("links", [])
            subject = data.get("subject")
            return {"subject": subject, "links": links}
    except Exception:
        pass  # fall back to XRD parsing

    # Try XRD (XML) parsing
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_elem = root.find("xrd:Subject", ns)
        subject = subject_elem.text if subject_elem is not None else None
        links = []
        for link in root.findall("xrd:Link", ns):
            rel = link.attrib.get("rel")
            href = link.attrib.get("href")
            template = link.attrib.get("template")
            type_ = link.attrib.get("type")
            link_dict = {}
            if rel:
                link_dict["rel"] = rel
            if href:
                link_dict["href"] = href
            if template:
                link_dict["template"] = template
            if type_:
                link_dict["type"] = type_
            if link_dict:
                links.append(link_dict)
        return {"subject": subject, "links": links}
    except Exception:
        return None

