def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        # Normalize settings_dirs to a list
        if isinstance(settings_dirs, str):
            dirs = [settings_dirs]
        else:
            dirs = list(settings_dirs)

        # Normalize spec_option to a list of patterns
        if spec_option is None:
            patterns = [None]
        elif isinstance(spec_option, (list, tuple)):
            patterns = list(spec_option)
        else:
            patterns = [spec_option]

        import os
        import glob

        result = []
        for d in dirs:
            if not os.path.isdir(d):
                continue
            for pat in patterns:
                if pat is None:
                    # All files in the directory
                    files = os.listdir(d)
                else:
                    # If the pattern contains glob wildcards, use glob
                    if any(ch in pat for ch in ('*', '?', '[')):
                        glob_path = os.path.join(d, pat)
                        files = [os.path.basename(f) for f in glob.glob(glob_path)]
                    else:
                        # Treat as a suffix filter
                        files = [f for f in os.listdir(d) if f.endswith(pat)]
                for f in files:
                    full_path = os.path.join(d, f)
                    if os.path.isfile(full_path):
                        result.append(full_path)
        return sorted(result)
    except Exception:
        return []

