def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # parser_dict: mapping of parser names to parser objects (assumed to be dict-like)
    # Each parser may contain an 'include' key with a list of other parser names to merge.
    # The merge is performed recursively, preserving existing keys in the target parser.
    def _merge_parser(target_name, target_parser, visited):
        if target_name in visited:
            # Avoid infinite recursion on circular includes
            return
        visited.add(target_name)
        includes = target_parser.get('include')
        if not includes:
            return
        if isinstance(includes, str):
            includes = [includes]
        for inc_name in includes:
            inc_parser = parser_dict.get(inc_name)
            if inc_parser is None:
                raise KeyError(f"Included parser '{inc_name}' not found for parser '{target_name}'.")
            # Recursively merge included parser first
            _merge_parser(inc_name, inc_parser, visited)
            # Merge options from inc_parser into target_parser, skipping 'include' key
            for key, value in inc_parser.items():
                if key == 'include':
                    continue
                if key not in target_parser:
                    target_parser[key] = value
        # After merging, remove the include directive to avoid reprocessing
        target_parser.pop('include', None)

    for pname, pparser in parser_dict.items():
        if isinstance(pparser, dict):
            _merge_parser(pname, pparser, set())
    return parser_dict

