def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        # Resolve the spec for the given command
        if isinstance(options_spec, dict):
            spec = options_spec.get(command_name, [])
        else:
            spec = options_spec

        required = []

        for opt in spec:
            # Skip if no condition
            if 'required_when' not in opt:
                continue

            cond = opt['required_when']
            name = opt.get('name') or opt.get('arg')
            if not name:
                continue

            matched = False
            try:
                if callable(cond):
                    # Callable receives the args dict
                    matched = bool(cond(args))
                elif isinstance(cond, dict):
                    # All key/value pairs must match
                    matched = all(args.get(k) == v for k, v in cond.items())
                elif isinstance(cond, str):
                    # Evaluate the expression with args as locals
                    matched = bool(eval(cond, {}, args))
                else:
                    # Unsupported condition type; ignore
                    matched = False
            except Exception:
                # If evaluation fails, treat as not matched
                matched = False

            if matched:
                required.append(name)

        return required

