def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg_name, arg_attrs in args.items():
        # Skip if not a dict of attributes
        if not isinstance(arg_attrs, dict):
            continue

        # Retrieve the value and the maximum allowed length
        value = arg_attrs.get('value')
        max_len = arg_attrs.get('length')

        # If no length constraint, nothing to validate
        if max_len is None:
            continue

        # Skip validation for None values
        if value is None:
            continue

        # Validate that max_len is a non-negative integer
        if not isinstance(max_len, int):
            raise TypeError(
                f"Length for argument '{arg_name}' must be an integer (got {type(max_len).__name__})"
            )
        if max_len < 0:
            raise ValueError(
                f"Length for argument '{arg_name}' must be non-negative (got {max_len})"
            )

        # Ensure the value has a length
        try:
            val_len = len(value)
        except Exception as exc:
            raise TypeError(
                f"Argument '{arg_name}' value of type {type(value).__name__} has no length"
            ) from exc

        # Compare the actual length with the maximum allowed
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' value length {val_len} exceeds maximum allowed {max_len}"
            )

