def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict")
    # Retrieve the mapping of argument names to allowed choices.
    # The structure is expected to be stored in self.parsed_yaml['choices'].
    choices = getattr(self, "parsed_yaml", {}).get("choices", {})
    for arg_name, value in args.items():
        if arg_name not in choices:
            continue
        allowed = choices[arg_name]
        # If the allowed value is a dict, use its keys as the valid set.
        if isinstance(allowed, dict):
            allowed_values = allowed.keys()
        else:
            allowed_values = allowed
        # Ensure the allowed values are iterable and not a string/bytes.
        if not hasattr(allowed_values, "__iter__") or isinstance(allowed_values, (str, bytes)):
            raise ValueError(
                f"Invalid choices definition for argument '{arg_name}': must be an iterable of allowed values"
            )
        # If the provided value is itself an iterable (but not a string/bytes),
        # validate each element individually.
        if isinstance(value, (list, tuple, set)) and not isinstance(value, (str, bytes)):
            for v in value:
                if v not in allowed_values:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': {v!r}. "
                        f"Allowed choices: {list(allowed_values)}"
                    )
        else:
            if value not in allowed_values:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value!r}. "
                    f"Allowed choices: {list(allowed_values)}"
                )

