def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping argument names to values")
    for name, val in args.items():
        if val is None:
            continue
        # Determine min and max values
        min_val = None
        max_val = None
        # If the value itself contains min/max information
        if isinstance(val, (tuple, list)) and len(val) == 3:
            val, min_val, max_val = val
        else:
            # Try to fetch min/max from the instance attributes
            min_attr = f"min_{name}"
            max_attr = f"max_{name}"
            if hasattr(self, min_attr) and hasattr(self, max_attr):
                min_val = getattr(self, min_attr)
                max_val = getattr(self, max_attr)
            else:
                raise ValueError(f"Missing min/max for argument '{name}'")
        # Validate that min and max are defined and comparable
        if min_val is None or max_val is None:
            raise ValueError(f"Both min and max must be defined for argument '{name}'")
        if min_val > max_val:
            raise ValueError(f"Minimum {min_val} greater than maximum {max_val} for argument '{name}'")
        # Perform the comparison
        try:
            if val < min_val:
                raise ValueError(f"Argument '{name}' value {val} below minimum {min_val}")
            if val > max_val:
                raise ValueError(f"Argument '{name}' value {val} above maximum {max_val}")
        except TypeError as exc:
            raise TypeError(f"Argument '{name}' value {val} is not comparable to min/max") from exc
    return args

