def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Determine the parsing strategy from spec_option, default to plain string
    parse_strategy = spec_option.get('parse', 'string')

    def complex_type(value):
        """Parse the argument value according to the specified strategy."""
        try:
            if parse_strategy == 'json':
                import json
                return json.loads(value)
            elif parse_strategy == 'list':
                # Split by comma and strip whitespace
                return [v.strip() for v in value.split(',') if v.strip()]
            elif parse_strategy == 'int':
                return int(value)
            elif parse_strategy == 'float':
                return float(value)
            else:
                # Default: return the raw string
                return value
        except Exception as exc:
            import argparse
            raise argparse.ArgumentTypeError(
                f"Invalid value for {option_name} in subcommand {subcommand}: {exc}"
            )

    # Attach helpful metadata for debugging and introspection
    complex_type.__name__ = f"{subcommand}_{type_name}_{option_name}_type"
    complex_type.__doc__ = (
        f"Complex type for option '{option_name}' in subcommand '{subcommand}'. "
        f"Parsing strategy: {parse_strategy}"
    )
    return complex_type

