def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Retrieve the parser object that contains option definitions
    parser = getattr(self, "parsers", {}).get(parser_name)
    if parser is None:
        raise ValueError(f"Parser '{parser_name}' not found")

    # Iterate over the options defined for this parser
    for opt in getattr(parser, "options", []):
        # Each option should have a name attribute
        name = getattr(opt, "name", None)
        if not name:
            continue

        # Only process options that were supplied
        if name not in values_dict:
            continue

        raw_value = values_dict[name]

        # If the option defines a custom convert method, use it
        if hasattr(opt, "convert") and callable(opt.convert):
            try:
                values_dict[name] = opt.convert(raw_value)
            except Exception as exc:
                raise ValueError(
                    f"Error converting option '{name}' using custom convert: {exc}"
                ) from exc
            continue

        # Otherwise, use the declared type if available
        opt_type = getattr(opt, "type", None)
        if opt_type is None:
            continue

        try:
            if opt_type is bool:
                # Convert common string representations of booleans
                if isinstance(raw_value, str):
                    values_dict[name] = raw_value.lower() in ("true", "1", "yes", "on")
                else:
                    values_dict[name] = bool(raw_value)
            elif opt_type is list:
                # Assume comma-separated values for lists
                if isinstance(raw_value, str):
                    values_dict[name] = [item.strip() for item in raw_value.split(",")]
                else:
                    values_dict[name] = list(raw_value)
            else:
                values_dict[name] = opt_type(raw_value)
        except Exception as exc:
            raise ValueError(
                f"Error converting option '{name}' to {opt_type}: {exc}"
            ) from exc

