def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    try:
        import yaml
    except ImportError:
        yaml = None

    if not isinstance(plugin_dir, str) or not os.path.isdir(plugin_dir):
        raise ValueError(f"Invalid plugin directory: {plugin_dir}")

    # Determine spec file: prefer JSON, fallback to YAML
    spec_path = None
    for fname in ("plugin.json", "plugin.yaml", "plugin.yml"):
        candidate = os.path.join(plugin_dir, fname)
        if os.path.isfile(candidate):
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    # Load spec
    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            if spec_path.endswith(".json"):
                spec = json.load(f)
            else:
                if yaml is None:
                    raise RuntimeError("PyYAML is required to parse YAML plugin specs")
                spec = yaml.safe_load(f)
    except Exception as e:
        raise ValueError(f"Failed to load plugin spec from {spec_path}: {e}")

    # Flatten nested dict
    def _flatten(d, parent_key="", sep="."):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    if not isinstance(spec, dict):
        raise ValueError(f"Plugin spec must be a mapping, got {type(spec)}")

    return _flatten(spec)

